/* Final layer: compact public layout; leaves operations/authentication unchanged. */
.tcVisuallyHidden {
  position:absolute;
  width:1px;
  height:1px;
  padding:0;
  overflow:hidden;
  clip:rect(0,0,0,0);
  white-space:nowrap;
  border:0
}
.tcSiteMenu {
  position:relative;
  justify-self:end;
  color:#06231c
}
.tcSiteMenu>summary {
  display:flex;
  align-items:center;
  gap:8px;
  list-style:none;
  min-height:44px;
  padding:8px 14px;
  border:1px solid #cad8ce;
  border-radius:12px;
  background:#fff;
  font-size:14px;
  font-weight:700;
  cursor:pointer
}
.tcSiteMenu>summary::-webkit-details-marker {
  display:none
}
.tcSiteMenu>summary svg {
  width:20px;
  height:20px
}
.tcSiteMenuPanel {
  position:absolute;
  right:0;
  top:calc(100% + 10px);
  width:min(330px,calc(100vw - 32px));
  max-height:calc(100dvh - 154px - env(safe-area-inset-bottom));
  overflow:auto;
  padding:16px;
  background:#fff;
  border:1px solid #d7e1d9;
  border-radius:16px;
  box-shadow:0 16px 40px #06231c24;
  z-index:110
}
.tcSiteMenuPanel nav {
  display:grid;
  gap:4px
}
.tcSiteMenuPanel button {
  min-height:44px;
  display:block;
  width:100%;
  text-align:left;
  border:0;
  border-radius:8px;
  background:transparent;
  padding:10px 12px;
  color:#06231c;
  font:inherit;
  font-size:14px;
  cursor:pointer
}
.tcSiteMenuPanel button:hover {
  background:#f0f6ef
}
.tcSiteMenuPanel .tcAccountInline {
  display:block;
  margin-top:12px;
  border-top:1px solid #d7e1d9;
  padding-top:12px
}
.tcSiteMenuPanel .tcAccountMenu {
  position:static;
  width:auto;
  border:0;
  box-shadow:none;
  padding:0;
  margin:10px 0 0
}
.tcSiteMenuPanel .tcAccountMenu p {
  font-size:13px
}
.tcSiteMenuPanel .tcAccountInline .tcAdminShortcut {
  width:100%;min-height:44px;box-sizing:border-box
}
.tcSiteMenuPanel .tcAccountInline .tcAdminEntryLink {
  width:100%;box-sizing:border-box
}
.tcSiteMenuPanel .tcCloseSiteMenu {
  margin-top:12px;
  border-top:1px solid #d7e1d9;
  font-weight:700
}
.tcSiteMenu summary:focus-visible,.tcSiteMenuPanel button:focus-visible {
  outline:3px solid #72ad18;
  outline-offset:3px
}
.tcOwnedEditor form {
  display:grid;
  gap:12px;
  padding:14px 0
}
.tcOwnedEditor label {
  display:grid;
  gap:6px
}
.tcOwnedEditor input:not([type=checkbox]),.tcOwnedEditor textarea,.tcOwnedEditor select {
  box-sizing:border-box;
  width:100%;
  max-width:100%;
  padding:10px;
  border:1px solid #bdcdc4;
  border-radius:8px
}
.tcOwnedEditor button {
  min-height:44px
}
/* Single public compact layer; operational/authentication views remain independent. */
.tcPosterThumb {
  float:right;
  margin:12px 12px 4px 8px;
  padding:0;
  width:64px;
  height:64px;
  border:1px solid #d6e0d5;
  border-radius:7px;
  background:#fff;
  overflow:hidden
}
.tcPosterThumb img {
  width:100%;
  height:100%;
  object-fit:contain
}
.tcDetailPoster {
  display:block;
  margin:16px;
  text-align:center;
  color:#154e38;
  font-size:14px
}
.tcDetailPoster img {
  display:block;
  max-width:100%;
  max-height:360px;
  object-fit:contain;
  margin:auto auto 8px
}
.neoShell .neoDrawer {
  grid-template-rows:auto 1fr
}
.neoShell .neoDrawerScroll {
  min-height:0;
  overflow:auto
}
.neoShell .neoDrawerHeader h2 {
  font-size:26px;
  line-height:1.2
}
.neoShell .neoDrawerHeader {
  padding:22px 20px 12px
}
.neoShell .neoDrawerClose {
  z-index:5;
  position:sticky;
  top:8px;
  float:right;
  margin:8px 8px 0 auto;
  min-width:44px;
  min-height:44px
}
.neoShell .neoDrawerGrid {
  padding:12px 20px
}
.neoShell .neoLoadMore {
  padding:14px 0;
  gap:8px
}
.neoShell .neoLoadMore small {
  font-size:13px
}
.neoShell .neoLoadMore button {
  min-height:44px;
  font-size:14px
}
.neoShell>.tcLocalAdvertising {
  width:calc(100% - 40px);
  max-width:1180px;
  box-sizing:border-box;
  margin:12px auto;
  padding:14px 16px
}
.tcTerritorialRadar,.tcSecondary {
  box-sizing:border-box;
  width:calc(100% - 40px);
  max-width:1180px;
  margin:12px auto;
  border:1px solid #d1dfd2;
  border-radius:12px;
  background:#fff;
  color:#123b2a;
  padding:16px;
  scroll-margin-top:82px
}
.tcRadarHeading {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px
}
.tcRadarHeading h2 {
  font-size:18px;
  margin:0
}
.tcRadarHeading p,.tcRadarNote {
  font-size:13px;
  line-height:1.4;
  margin:5px 0;
  color:#526b5b
}
.tcRadarHeading>svg {
  width:20px;
  height:20px
}
.tcRadarExplorer {
  display:grid;
  grid-template-columns:180px minmax(0,1fr);
  align-items:center;
  gap:20px;
  margin-top:10px
}
.tcRadarDial {
  position:relative;
  width:180px;
  height:180px;
  flex-shrink:0;
  border-radius:50%;
  overflow:hidden;
  border:1px solid #7b9c83;
  background:#0b3025
}
.tcRadarSweep {
  position:absolute;
  inset:0;
  background:conic-gradient(from 0deg,transparent 0 260deg,#99ef4d65 359deg,transparent 360deg);
  animation:tcSweep 10s linear infinite;
  animation-play-state:paused
}
.tcTerritorialRadar[data-animated=true] .tcRadarPoint.selected {
  animation-play-state:running;
}
@keyframes tcRadarFocus {
  from { opacity:.65; transform:translate(-50%,-50%) scale(1.25); }
  to { opacity:1; transform:translate(-50%,-50%) scale(1); }
}
.tcTerritorialRadar[data-animated=true] .tcRadarSweep {
  animation-play-state:running
}
.tcRadarDial .tcRadarPoint {
  position:absolute;
  width:7px;
  height:7px;
  border-radius:50%;
  background:#809688;
  transform:translate(-50%,-50%)
}
.tcRadarDial .tcRadarPoint.available {
  background:#b7ff4e
}
.tcRadarDial .tcRadarPoint.unknown {
  background:#d2c087
}
.tcRadarDial .tcRadarPoint.selected {
  background:#ffb396;
  box-shadow:0 0 0 4px #ffffff35;
  animation:tcRadarFocus .6s ease-out;
  animation-play-state:paused
}
.tcRadarCaption {
  position:absolute;
  bottom:22%;
  left:4%;
  right:4%;
  text-align:center;
  font-size:13px;
  color:#fff;
  line-height:1.3;
  text-shadow:0 1px 4px #000
}
.tcRadarDial b {
  display:block;
  font-size:12px
}
.tcRadarTowns {
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(118px,1fr));
  gap:6px;
  width:100%
}
.tcRadarTowns button {
  display:flex;
  flex-direction:column;
  justify-content:center;
  text-align:left;
  gap:3px;
  border:1px solid #d5e0d2;
  border-radius:8px;
  padding:6px 8px;
  min-height:44px;
  background:#f9fbf6;
  color:#123b2a;
  font-size:13px;
  cursor:pointer
}
.tcRadarTowns small {
  font-size:11px;
  color:#536752
}
.tcRadarTowns button[aria-pressed=true] {
  border-color:#5a8b3c;
  background:#e8f5dc
}
.tcRadarNote {
  display:block;
  margin-top:10px
}
.tcSecondary>summary {
  font-size:14px;
  min-height:44px;
  display:flex;
  align-items:center;
  cursor:pointer;
  font-weight:650;
  list-style:revert
}
.tcActivityBackdrop {
  z-index:1500;
  background:#05241c70;
  display:grid;
  place-items:center;
  padding:16px
}
.tcActivityCenter {
  width:min(100%,520px);
  max-height:calc(100dvh - 32px);
  overflow:auto;
  box-sizing:border-box;
  border-radius:16px;
  padding:22px;
  background:#fff;
  color:#123b2a;
  position:relative;
  font-size:14px;
  line-height:1.45;
  outline:none
}
.tcActivityCenter h2 {
  font-size:24px;
  margin:0 44px 12px 0
}
.tcActivityCenter p {
  margin:10px 0
}
.tcActivityCenter label {
  display:grid;
  gap:5px
}
.tcActivityCenter select {
  min-height:44px;
  padding:8px;
  font-size:16px;
  width:100%;
  max-width:100%;
  box-sizing:border-box
}
.tcActivityCenter button {
  min-height:44px;
  padding:8px 12px;
  font-size:14px;
  line-height:1.35;
  border:1px solid #c6d6c9;
  border-radius:8px;
  background:#f3f8ef;
  color:#123b2a;
  margin:4px 5px 4px 0
}
.tcActivityCenter .tcActivityClose {
  position:absolute;
  right:10px;
  top:8px;
  min-width:44px;
  background:white;
  padding:8px
}
.tcActivityClose svg {
  width:20px;
  height:20px
}
.tcRadarDetails>summary {
  display:none
}
@keyframes tcSweep {
  to {
    transform:rotate(360deg)
  }
}
@media(max-width:800px) {
  .tcSiteMenu>summary {
    padding:4px 9px;
    gap:5px;
    font-size:12px;
    min-height:44px
  }
  .tcSiteMenu>summary svg {
    width:18px;
    height:18px
  }
  .neoShell>.tcLocalAdvertising {
    width:calc(100% - 28px);
    margin:10px auto;
    padding:12px
  }
  .tcTerritorialRadar,.tcSecondary {
    width:calc(100% - 28px);
    padding:10px;
    margin:8px auto;
    scroll-margin-top:8px
  }
  .tcRadarHeading h2 {
    font-size:16px
  }
  .tcRadarHeading p {
    font-size:11px;
    line-height:1.25
  }
  .tcRadarExplorer {
    grid-template-columns:minmax(0,1fr);
    gap:8px;
    align-items:stretch
  }
  .tcRadarDial {
    width:120px;
    height:120px;
    position:relative;
    top:auto;
    justify-self:center
  }
  .tcRadarCaption {
    font-size:10px;
    bottom:20%
  }
  .tcRadarDial b {
    font-size:10px
  }
  .tcRadarTowns {
    grid-template-columns:repeat(3,minmax(0,1fr));
    gap:4px;
    max-height:none;
    overflow:visible;
    padding:0
  }
  .tcRadarTowns button {
    font-size:10.5px;
    line-height:1.18;
    padding:4px 6px;
    gap:1px;
    min-height:44px
  }
  .tcRadarTowns small {
    font-size:10px
  }
  .tcRadarNote {
    font-size:10.5px;
    line-height:1.3;
    margin-top:7px
  }
  .tcRadarDetails>summary {
    display:flex;
    align-items:center;
    justify-content:space-between;
    min-height:44px;
    font-size:11.5px;
    font-weight:650;
    color:#1e5035;
    cursor:pointer;
    list-style:none
  }
  .tcRadarDetails>summary::-webkit-details-marker {
    display:none
  }
  .tcRadarDetails>summary span {
    font-size:18px
  }
  .neoShell .neoNotice {
    bottom:calc(64px + env(safe-area-inset-bottom))
  }
  .neoShell a {
    scroll-margin-bottom:calc(68px + env(safe-area-inset-bottom))
  }
  .neoShell .neoDrawer {
    width:100%;
    max-width:100%
  }
}
@media(prefers-reduced-motion:reduce) {
  .neoShell * {
    scroll-behavior:auto!important;
    animation:none!important;
    transition:none!important
  }
}
.tcResultsPagination {
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:6px;
  flex-wrap:wrap;
  padding:9px 0
}
.tcResultsPagination button {
  min-height:44px;
  padding:7px 10px;
  border:1px solid #cbd9cf;
  border-radius:8px;
  background:#fff;
  color:#123b2a;
  font-size:12.5px
}
.tcResultsPagination button:disabled {
  opacity:.5
}
.tcResultsPagination span {
  font-size:12px
}
@media(max-width:800px) {
  .tcResultsPagination {
    display:grid;
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:6px
  }
  .tcResultsPagination span {
    grid-column:1/-1;
    grid-row:1;
    font-size:12px
  }
  .tcResultsPagination button {
    width:100%;
    min-width:0
  }
}
.neoShell .neoNotice>button {
  min-width:44px;
  min-height:44px
}
/* Shared compact creative layout: no hero photographs. */
.tcLocalAdvertising .tcAdImage {
  display:block;
  width:104px;
  height:82px;
  object-fit:cover;
  border-radius:10px
}
.tcLocalAdvertising .tcAdContent {
  display:grid;
  grid-template-columns:auto minmax(0,1fr) auto;
  gap:14px;
  align-items:center
}
.tcLocalAdvertising .tcAdContent:not(:has(>.tcAdImage)) {
  grid-template-columns:minmax(0,1fr) auto
}
.tcAdLogo {
  display:inline-block;
  width:32px;
  height:32px;
  object-fit:contain;
  vertical-align:middle;
  margin-right:8px;
  border-radius:5px
}
.tcLocalAdvertising .tcAdContent>div {
  min-width:0
}
.tcLocalAdvertising small {
  font-size:11px
}
@media(max-width:800px) {
  .tcLocalAdvertising .tcAdContent {
    grid-template-columns:64px minmax(0,1fr);
    gap:10px
  }
  .tcLocalAdvertising .tcAdImage {
    width:64px;
    height:64px
  }
  .tcLocalAdvertising .tcAdContent>a {
    grid-column:1/-1;
    justify-self:start;
    min-height:44px
  }
  .tcLocalAdvertising .tcAdContent:not(:has(>.tcAdImage)) {
    grid-template-columns:minmax(0,1fr)
  }
  .tcAdLogo {
    width:26px;
    height:26px
  }
}
.tcLocalAdvertising .tcAdBusiness {
  display:flex;
  align-items:center;
  gap:6px
}
.tcLocalAdvertising .tcAdBusiness .tcAdLogo {
  flex-shrink:0;
  margin-right:0
}
.tcLocalAdvertising .tcAdBusiness strong {
  margin:0;
  min-width:0;
  overflow-wrap:anywhere
}
/* Fine rings and native accordion affordances. */
.tcRadarDial .tcRadarGrid {
  position:absolute;
  inset:0;
  display:block;
  width:100%;
  height:100%;
  stroke:#719c7b;
  stroke-width:.8;
  opacity:.65;
  pointer-events:none
}
.tcRadarDial .tcRadarPoint {
  display:block;
  padding:0;
  margin:0;
  min-width:0;
  min-height:0;
  border:0;
  box-sizing:border-box
}
.tcRadarTowns button span {
  white-space:normal;
  overflow:visible;
  text-overflow:clip;
  line-height:1.3
}
.tcSecondary>summary {
  display:flex;
  justify-content:space-between;
  gap:12px;
  list-style:none;
  line-height:1.35
}
.tcSecondary>summary::-webkit-details-marker {
  display:none
}
.tcSecondary>summary::after {
  content:'+';
  display:grid;
  place-items:center;
  flex:0 0 24px;
  width:24px;
  height:24px;
  border-radius:50%;
  background:#eef5e8;
  font-size:20px;
  font-weight:400;
  color:#224c32
}
.tcSecondary[open]>summary::after {
  content:'−'
}
/* Public footer: one owner, no card-sized legal links or email gaps. */

/* Trabajo Cerca mobile utility controls: compact consumer-app proportions. */
.tcNotifyPanel button:focus-visible,.tcInstallGuide button:focus-visible{outline:2px solid #5b8a23;outline-offset:2px}
.tcInstallBackdrop,.tcNotifyBackdrop{z-index:1550}
.tcInstallGuide{position:relative;max-width:430px;width:min(100%,430px);max-height:calc(100dvh - 30px);overflow:auto;background:#fff;border-radius:16px;border:1px solid #d4dfd5;padding:20px;box-shadow:0 16px 40px #061b1433;color:#12382a}
.tcInstallGuide h2{font-size:20px;margin:0 42px 6px 0;line-height:1.2}
.tcInstallGuide p{font-size:13px;line-height:1.4;margin:6px 0 12px}
.tcInstallGuide>div{border-top:1px solid #e0e7e0;padding:10px 0 0}
.tcInstallGuide>div b{font-size:13px}
.tcInstallGuide>small{display:block;color:#53665c;font-size:11px;line-height:1.4;margin-top:10px}
.tcInstallGuide button{min-height:44px;border-radius:9px;border:1px solid #c9d6ca;font-size:12px;cursor:pointer}
.tcInstallClose{position:absolute;right:14px;top:12px;width:44px;height:44px;background:#fff}
.tcInstallClose svg{height:18px;width:18px}
.tcInstallDone{margin-top:12px;padding:8px 14px;color:white;background:#0b3326;border:0!important}
.neoAlertsModal.tcNotifyBackdrop{padding:12px;align-items:center}
.neoAlertsModal .tcNotifyPanel{display:block;width:min(440px,100%);max-height:calc(100dvh - 24px);border-radius:15px;overflow:auto;background:#fff;box-shadow:0 14px 40px #061b1438}
.neoAlertsModal .tcNotifyForm{display:flex;flex-direction:column;gap:10px;padding:20px}
.tcNotifyHeading{display:flex;align-items:flex-start;gap:10px;padding-right:40px}
.tcNotifyHeading .tcNotifyIcon{width:34px;height:34px;display:grid;place-items:center;border-radius:10px;background:#eaf5df;color:#1d532e;flex:none}
.tcNotifyHeading svg{width:19px;height:19px}
.neoAlertsModal .tcNotifyHeading h2{font-size:20px;line-height:1.18;margin:0 0 5px;color:#0b3425;letter-spacing:-.02em}
.neoAlertsModal .tcNotifyHeading p{font-size:12px;line-height:1.35;margin:0;color:#52665c}
.neoAlertsModal .tcNotifyMainPlace{display:grid;gap:5px;font-size:12px;font-weight:650;color:#234c38}
.neoAlertsModal .tcNotifyMainPlace select{width:100%;height:44px;min-height:44px;padding:8px 10px;border:1px solid #c9d6cb;border-radius:9px;background:#fff;color:#0b3326;font-size:14px}
.tcNotifyMore{border:1px solid #dae4d8;border-radius:9px;padding:0 10px}
.tcNotifyMore>summary{list-style:none;cursor:pointer;min-height:44px;display:flex;align-items:center;font-size:12px;font-weight:650}
.tcNotifyMore>summary::after{content:'+';margin-left:auto;font-size:19px;font-weight:400}
.tcNotifyMore[open]>summary::after{content:'−'}
.tcNotifyMore>summary::-webkit-details-marker{display:none}
.neoAlertsModal .tcNotifyMore p{font-size:11px;margin:0 0 6px}
.neoAlertsModal .tcNotifyMore .neoAlertPlaces{max-height:132px;display:flex;flex-wrap:wrap;gap:5px}
.neoAlertsModal .tcNotifyMore .neoAlertPlaces button{min-height:34px;font-size:11px;padding:6px 9px;border-radius:8px}
.neoAlertsModal .tcNotifyMore .neoAlertKeywords{font-size:12px;display:grid;gap:4px;margin:9px 0 10px}
.neoAlertsModal .tcNotifyMore input{min-height:44px;width:100%;border:1px solid #cdd8cd;border-radius:8px;padding:7px 9px;font-size:14px;box-sizing:border-box}
.neoAlertsModal .tcNotifyNote{font-size:11px;line-height:1.4;color:#607365;margin:0}
.neoAlertsModal .tcNotifyActions{display:flex;gap:6px;flex-wrap:wrap;margin:0;padding:2px 0}
.neoAlertsModal .tcNotifyActions button{min-height:44px;border-radius:8px;font-size:12px;line-height:1.2;padding:7px 12px}
.neoAlertsModal .tcNotifyActions .neoAlertPrimary{flex:1 1 140px;white-space:nowrap}
.neoAlertsModal .tcNotifyActions .neoAlertTest,.neoAlertsModal .tcNotifyActions .neoAlertDisable{flex:1 1 95px}
.neoAlertsModal .tcNotifyForm .neoAlertFoot{font-size:10px;line-height:1.4;margin:0}
.tcNotifyActive{display:flex;align-items:center;gap:6px;font-size:11px;line-height:1.35;color:#245834;background:#edf7e8;padding:8px;border-radius:8px}
.tcNotifyActive svg{height:16px;width:16px;flex-shrink:0}
.neoAlertsModal .neoAlertsClose{top:10px;right:10px;width:44px;height:44px;border-radius:9px;box-shadow:none;background:#f6f9f5;border:1px solid #dfebdf}
.tcActivityCenter{padding:16px;width:min(100%,430px);max-height:calc(100dvh - 24px);border-radius:14px;font-size:12px}
.tcActivityHeading{display:flex;gap:9px;align-items:flex-start;padding-right:38px}
.tcActivityHeading>svg{height:21px;width:21px;color:#2c5b39;flex-shrink:0}
.tcActivityCenter .tcActivityHeading h2{margin:0;font-size:19px;line-height:1.2}
.tcActivityHeading p{font-size:12px!important;color:#586f61;margin:3px 0 8px!important}
.tcActivityCenter .tcActivitySelect{font-size:12px;font-weight:650;gap:4px}
.tcActivityCenter .tcActivitySelect select{border:1px solid #ccd9cd;border-radius:8px;padding:6px 9px;font-size:14px}
.tcActivityMetric{display:flex;align-items:center;gap:8px;padding:8px 0;font-size:12px}
.tcActivityMetric strong{font-size:23px;line-height:1;color:#0a3c2a}
.tcActivityActions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}
.tcActivityCenter .tcActivityActions button{width:100%;margin:0;font-size:11.5px;padding:7px}
.tcActivityCenter .tcActivityPush{display:flex;gap:7px;align-items:center;justify-content:center;width:100%;margin:9px 0 4px;padding:8px;background:#0b3428;color:#fff;border:0;font-size:12px}
.tcActivityPush svg{width:17px;height:17px}
