/** Presentation contracts for read-only backend metrics.
 * Figures are measured, never filled with simulated data.
 */
export type AdminSnapshot={
 publicVisible?:number;jobs?:number;verified?:number;pending?:number;
 campaigns?:number;requests?:number;lastSweep?:string;
};
export type EngineId='A'|'B'|'C'|'D'|'CHATGPT'|'GEMINI';
export type EngineRole='discovery'|'documents';
export type EngineStatus='recent'|'stale'|'unreported'|'error';
export type EngineRow={
 id:EngineId;name:string;role:EngineRole;status:EngineStatus;observedAt:string|null;
 source:string;scope:string;notes:string[];
 counts:{scheduled:number|null;attempted:number|null;useful:number|null;blocked:number|null;
 candidates:number|null;verified:number|null;queued:number|null;
 publishedConfirmed:number|null;processed:number|null};
};
export type DayPoint={day:string;engine:EngineId;measure:'sources_attempted'|'docs_processed';value:number};
export type Telemetry={
 schemaVersion:number;readOnly:boolean;generatedAt:string;engines:EngineRow[];
 rollup:{recent:number;reporting:number;total:number};
 history:DayPoint[];historyComplete:boolean;
 missingOrFailed:EngineId[];warning:string;
};
export type ExecutiveKpi={key:string;label:string;value:string;note:string;accent:string};
export const MAIN_CITIES=[
 'Angol','Collipulli','Ercilla','Lumaco','Los Sauces','Purén','Renaico',
 'Traiguén','Victoria','Mulchén','Negrete','Nacimiento'
] as const;
export function knownCount(value:unknown):string{
 return typeof value==='number'&&Number.isSafeInteger(value)&&value>=0?String(value):'Sin datos';
}
export function percent(part:unknown,total:unknown):number|null {
 return typeof part==='number'&&typeof total==='number'&&
  Number.isSafeInteger(part)&&part>=0&&Number.isSafeInteger(total)&&total>0&&part<=total
    ?Math.round((part/total)*100):null;
}
export function formatRatio(part:unknown,total:unknown):string{
 const p=percent(part,total);
 return p===null?'Sin datos':p+' %';
}
export function executiveKpis(s?:AdminSnapshot,t?:Telemetry|null):ExecutiveKpi[]{
 const d=t?.engines?.find(e=>e.id==='D');
 const a=t?.engines?.find(e=>e.id==='A');
 const readable=d?.counts.attempted!==null&&d?.counts.attempted!==undefined?d:a;
 const ratio=readable?formatRatio(readable.counts.useful,readable.counts.attempted):'Sin datos';
 return [
  {key:'visible',label:'Ofertas públicas',value:knownCount(s?.publicVisible),
   note:'En el catálogo, no nuevas del día',accent:'blue'},
  {key:'readable',label:'Lectura útil · '+(readable?.name||'motores'),value:ratio,
   note:readable?'Fuentes accesibles / intentadas del último ciclo':'Aún sin reporte válido',accent:'teal'},
  {key:'motors',label:'Motores con reporte reciente',
   value:t?knownCount(t.rollup.recent)+' / '+knownCount(t.rollup.total):'Sin datos',
   note:'Actividad observada, no cobertura completa',accent:'violet'},
  {key:'pending',label:'Candidatos pendientes',value:knownCount(s?.pending),
   note:'Conteo interno consultado; no publicados',accent:'amber'},
  {key:'ads',label:'Campañas publicitarias',value:knownCount(s?.campaigns),
   note:'Solicitudes por revisar: '+knownCount(s?.requests),accent:'green'}
 ];
}
export type CityCount={city:string;visible:string;audited:string;expected:string;failed:string};
type Row=Record<string,unknown>;
export function cityCounts(payload:unknown):CityCount[]{
 const record=payload&&typeof payload==='object'&&!Array.isArray(payload)?payload as Record<string,unknown>:{};
 const items=Array.isArray(record.communes)?record.communes:[];
 const byCity=new Map<string,Row>();
 for(const item of items){
  if(!item||typeof item!=='object'||Array.isArray(item))continue;
  const row=item as Row;
  if(typeof row.city==='string'&&MAIN_CITIES.includes(row.city as typeof MAIN_CITIES[number]))byCity.set(row.city,row);
 }
 return MAIN_CITIES.map(city=>{
  const row=byCity.get(city);
  return {city,visible:knownCount(row?.publicJobs),
   audited:knownCount(row?.sourceChecked),expected:knownCount(row?.sourceConfigured),
   failed:knownCount(row?.sourceFailed)};
 });
}
export function chartValues(points:DayPoint[],engine:'A'|'B'|'C'):DayPoint[]{
 return points.filter(p=>p.engine===engine&&
   (engine==='A'?p.measure==='sources_attempted':p.measure==='docs_processed')&&
   /^\d{4}-\d{2}-\d{2}$/.test(p.day)&&Number.isSafeInteger(p.value)&&p.value>=0)
   .sort((a,b)=>a.day.localeCompare(b.day)).slice(-8);
}
export function engineStatus(status:EngineStatus):string{
 return {recent:'Registro reciente',stale:'Sin ejecución reciente',unreported:'Sin reporte',
   error:'Requiere revisión'}[status];
}

type Item = { id:string; [key:string]:unknown };
type Page = { items:Item[]; nextCursor?:string | null; totalItems?:number; totalJobOffers?:number };
type Read = (path:string) => Promise<{ data:Page }>;

// Read every page through the frontend SDK; finding expected IDs is not a stop condition.
export async function readFeedInventory(read:Read, maxPages=100) {
  const items:Item[] = [];
  const ids = new Set<string>(), cursors = new Set<string>();
  let cursor:string | undefined, pagesRead=0, totalItems:number | undefined;
  let totalJobOffers:number | undefined;
  try {
    if (!Number.isInteger(maxPages) || maxPages<1 || maxPages>100) throw new Error('invalid_limit');
    while (pagesRead<maxPages) {
      const suffix=cursor ? '&cursor='+encodeURIComponent(cursor) : '';
      const { data }=await read('/api/listings?fresh=1'+suffix);
      if (!Array.isArray(data.items)) throw new Error('invalid_items');
      if (pagesRead===0) { totalItems=data.totalItems;totalJobOffers=data.totalJobOffers; }
      pagesRead++;
      for (const item of data.items) {
        if (typeof item.id!=='string' || !item.id || ids.has(item.id)) throw new Error('duplicate_or_invalid_id');
        ids.add(item.id);
        const { id,kind,title,company,source,workLocation,workCommunes,date,createdAt,url,verified,review,
          sourcePublishedAt,sourceValidThrough,expiresAt,applicationUrl,applicationMethod,firstPublishedAt,lastVerifiedAt,externalVerifiedAt,revalidationDue,active,closureReason }=item;
        items.push({ id,kind,title,company,source,workLocation,workCommunes,date,createdAt,url,verified,review,
          sourcePublishedAt,sourceValidThrough,expiresAt,applicationUrl,applicationMethod,firstPublishedAt,lastVerifiedAt,externalVerifiedAt,revalidationDue,active,closureReason });
      }
      if (!data.nextCursor) {
        if (totalItems!==undefined && (!Number.isSafeInteger(totalItems) || totalItems!==items.length)) throw new Error('incomplete_count');
        return { items,pagesRead,totalItems,totalJobOffers,complete:true,error:null };
      }
      if (typeof data.nextCursor!=='string' || cursors.has(data.nextCursor)) throw new Error('repeated_or_invalid_cursor');
      cursors.add(data.nextCursor);cursor=data.nextCursor;
    }
    throw new Error('page_limit_reached');
  } catch {
    return { items,pagesRead,totalItems,totalJobOffers,complete:false,error:'No se pudo completar la lectura de todas las páginas del feed.' };
  }
}

type Page<T>={items:T[];nextCursor?:string|null;degraded?:boolean;feedRebuilding?:boolean};
/** Read one immutable feed manifest in bounded pairs.
 * Page occupancy varies: totalItems/pageSize MUST NOT predict the last page.
 * The authoritative nextCursor (or its absence) ends the traversal.
 * A speculative second request can return 400 on an odd final page; it is
 * ignored ONLY when the preceding verified page has no continuation cursor.
 */
export async function readRemaining<T>(
 cursor:string,_total:number,_size:number,
 read:(cursor:string)=>Promise<Page<T>>,alive:()=>boolean
):Promise<T[]>{
 const match=/^v2:([A-Za-z0-9_-]{1,128}):(\d+)$/.exec(cursor);
 const start=match?Number(match[2]):NaN;
 const verify=(r:Page<T>):T[]=>{
  if(!alive()||!r||!Array.isArray(r.items)||r.degraded||r.feedRebuilding)
   throw Error('Incomplete public job inventory');
  return r.items;
 };
 if(match&&Number.isSafeInteger(start)&&start>=1){
  const prefix='v2:'+match[1]+':';
  const items:T[]=[];
  let index=start;
  for(let pair=0;pair<30;pair++){
   if(!alive())throw Error('Cancelled public feed');
   const responses=await Promise.allSettled([read(prefix+index),read(prefix+(index+1))]);
   const first=responses[0];
   if(first.status==='rejected')throw first.reason;
   items.push(...verify(first.value));
   // If the first page is last, its cursor ends the read. No count inference.
   if(!first.value.nextCursor)return items;
   if(first.value.nextCursor!==prefix+(index+1))
     throw Error('Public feed cursor mismatch');
   const second=responses[1];
   if(second.status==='rejected')throw second.reason;
   items.push(...verify(second.value));
   if(!second.value.nextCursor)return items;
   if(second.value.nextCursor!==prefix+(index+2))
     throw Error('Public feed cursor mismatch');
   index+=2;
   await new Promise(resolve=>setTimeout(resolve,120));
  }
  throw Error('Public feed page bound reached');
 }
 // Legacy pages: cursor-linked sequential fallback; no speculative index.
 const items:T[]=[];const visited=new Set<string>();let next:string|null=cursor;
 for(let page=0;next&&page<60;page++){
  if(!alive()||visited.has(next))throw Error('Public feed interrupted');
  visited.add(next);const r=await read(next);items.push(...verify(r));next=r.nextCursor||null;
  if(next)await new Promise(resolve=>setTimeout(resolve,140));
 }
 if(next)throw Error('Public feed page bound reached');
 return items;
}

type VisibleItem={kind:string;createdAt:string;firstPublishedAt?:string;workCommunes:string[];review?:boolean};
type InventorySummary={totalJobOffers:number;recentJobOffers7d?:number;recentJobOffers24h?:number;communeStats:Record<string,{jobs:number;newJobs7d?:number;newJobs24h:number}>};
const PRESENTATION_DAY=86400000;

export function recentInApp(item:VisibleItem,now=Date.now(),days=7) {
  const first=Date.parse(item.firstPublishedAt || item.createdAt);
  return item.kind==='job_offer' && Number.isFinite(first) && first<=now && first>=now-days*PRESENTATION_DAY;
}

// Counts come from the complete immutable feed, never the loaded card page or
// the sum of communes (an offer can belong to more than one commune).
export function publishedInventoryCounts(summary:InventorySummary,place='Todas') {
  const selected=place==='Todas' ? null : summary.communeStats[place];
  return {total:place==='Todas' ? summary.totalJobOffers : selected?.jobs ?? 0,
    recent7d:place==='Todas' ? summary.recentJobOffers7d ?? null : selected?.newJobs7d ?? null,
    recent24h:place==='Todas' ? summary.recentJobOffers24h ?? null : selected?.newJobs24h ?? 0};
}

